sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

/**
     * Requirement: Secure Inbound API to create Telecom Incidents for Bank ABC.
     */

    var bank_ABC_Comp_ID = gs.getProperty('x_1520874_teleco_0.bank_ABC_Comp_ID');
    try {
        var requestBody = request.body.data;

        if (!requestBody.short_description || 
            !requestBody.network_node || 
            !requestBody.outage_scale || 
            !requestBody.network_technology || 
            !requestBody.affected_network_element ||
			!requestBody.priority) {

            response.setStatus(400); 
            return { 
                "status": "error", 
                "message": "Missing mandatory fields. Required: short_description, network_node, outage_scale, network_technology, affected_network_element ,priority." 
            };
        }

        var incGr = new GlideRecord('x_1520874_teleco_0_x_telecom_incident');
        incGr.initialize();

        incGr.short_description = "Automated Alert: " + requestBody.short_description;
        incGr.description = "System detected an issue on node: " + requestBody.network_node;

        incGr.company = bank_ABC_Comp_ID;

		incGr.outage_scale = requestBody.outage_scale; 
        incGr.network_technology = requestBody.network_technology;
		incGr.affected_network_element = requestBody.affected_network_element;
		incGr.priority = requestBody.priority;
        var incSysId = incGr.insert();

        response.setStatus(201); 
        return {
            "status": "success",
            "incident_number": incGr.number.toString(),
            "message": "Telecom incident successfully created securely for Bank ABC."
        };

    } catch (ex) {
        //  ERROR HANDLING & LOGGING (System resilience)
        gs.error('Bank ABC API Error: ' + ex.message);
        response.setStatus(500); // 500 Internal Server Error
        return {
            "status": "error",
            "message": "An internal server error occurred while processing the request."
        };
    }
})(request, response);
